import{_ as e,o as t,c as l,a5 as i}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"学习状态模板","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/learning-state.zh.md","filePath":"public/downloads/worksheets/learning-state.zh.md","lastUpdated":1795488252000}'),r={name:"public/downloads/worksheets/learning-state.zh.md"};function n(h,a,o,s,d,u){return t(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="学习状态模板" tabindex="-1">学习状态模板 <a class="header-anchor" href="#学习状态模板" aria-label="Permalink to &quot;学习状态模板&quot;">​</a></h1><p>复制下列模板到自己的私有笔记。它是跨会话的事实源，不是展示自律的日记。不要写入密码、证件、精确住址、医疗隐私或未获授权的第三方信息。</p><h2 id="如果今天只有五分钟" tabindex="-1">如果今天只有五分钟 <a class="header-anchor" href="#如果今天只有五分钟" aria-label="Permalink to &quot;如果今天只有五分钟&quot;">​</a></h2><p>不要先把整张表填完。复制下面的最小版本，写完就去做动作；只有当任务需要跨会话、交接或复盘时，再补充完整模板。</p><h3 id="learning-state-—-minimum" tabindex="-1">Learning State — minimum <a class="header-anchor" href="#learning-state-—-minimum" aria-label="Permalink to &quot;Learning State — minimum&quot;">​</a></h3><p>日期：YYYY-MM-DD<br> 我正在处理的真实问题：<br> 我已经拥有的证据：<br> 今天能完成的最小动作：<br> 完成后要留下的证据：<br> 我不会上传或公开的内容：</p><p>最小版本的完成标准是：另一个未来的自己能看懂现在要解决什么、已经知道什么、下一步做什么，以及哪些边界不能越过。它不是完整计划，也不能替代独立复测；它只是让行动先发生。</p><h3 id="learning-state" tabindex="-1">Learning State <a class="header-anchor" href="#learning-state" aria-label="Permalink to &quot;Learning State&quot;">​</a></h3><p>状态版本：v1<br> 更新时间：YYYY-MM-DD<br> 维护人：<br> 主文件位置：</p><h4 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h4><ul><li>真实场景：</li><li>当前主任务：</li><li>12 周结果：</li><li>本周重点：</li><li>完成标准：</li><li>截止日期：</li></ul><h4 id="约束与边界" tabindex="-1">约束与边界 <a class="header-anchor" href="#约束与边界" aria-label="Permalink to &quot;约束与边界&quot;">​</a></h4><ul><li>每周可用时间/精力：</li><li>可以使用的材料与工具：</li><li>不应上传或公开的内容：</li><li>AI 可以协助：</li><li>必须由人确认：</li></ul><h4 id="当前水平与基线" tabindex="-1">当前水平与基线 <a class="header-anchor" href="#当前水平与基线" aria-label="Permalink to &quot;当前水平与基线&quot;">​</a></h4><ul><li>我现在能完成：</li><li>基线样本位置：</li><li>最近一次评分/反馈：</li></ul><table tabindex="0"><thead><tr><th>样本</th><th>条件</th><th>位置</th><th>日期</th><th>仍然不能说明什么</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h4 id="已完成" tabindex="-1">已完成 <a class="header-anchor" href="#已完成" aria-label="Permalink to &quot;已完成&quot;">​</a></h4><ul><li>[日期] 任务 — 输出/证据位置 — 结果/下一步</li></ul><h4 id="错误、风险与待补知识" tabindex="-1">错误、风险与待补知识 <a class="header-anchor" href="#错误、风险与待补知识" aria-label="Permalink to &quot;错误、风险与待补知识&quot;">​</a></h4><table tabindex="0"><thead><tr><th>错误/风险</th><th>证据</th><th>可能原因/置信度</th><th>下一次处理与停止条件</th></tr></thead></table><h4 id="已验证有效的方法" tabindex="-1">已验证有效的方法 <a class="header-anchor" href="#已验证有效的方法" aria-label="Permalink to &quot;已验证有效的方法&quot;">​</a></h4><ul><li>方法 — 在什么条件下有效 — 证据</li></ul><h4 id="待验证假设" tabindex="-1">待验证假设 <a class="header-anchor" href="#待验证假设" aria-label="Permalink to &quot;待验证假设&quot;">​</a></h4><ul><li>假设 — 反例 — 下一次怎么检验 — 截止日期</li></ul><h4 id="最近一次交接" tabindex="-1">最近一次交接 <a class="header-anchor" href="#最近一次交接" aria-label="Permalink to &quot;最近一次交接&quot;">​</a></h4><ul><li>已完成与证据：</li><li>仍未确认的事实：</li><li>未决选择：</li><li>已发生的成本/返工：</li><li>下一次打开文件先做什么：</li><li>需要通知或征求意见的人：</li></ul><h4 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h4><ol><li>下一项最小任务：</li><li>预计时长：</li><li>需要材料：</li><li>完成后保存什么证据：</li><li>下次复查日期：</li></ol><h2 id="ai-跨会话恢复提示词" tabindex="-1">AI 跨会话恢复提示词 <a class="header-anchor" href="#ai-跨会话恢复提示词" aria-label="Permalink to &quot;AI 跨会话恢复提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是我的学习状态文件。先用不超过 6 条要点复述状态版本、目标、当前证据、主要错误、边界和下一步，指出信息冲突或缺口，不要假装记得其他会话，也不要补写文件里没有的事实。然后只为“下一项最小任务”设计一次练习：先让我作答，再按完成标准反馈；除非我请求，不要直接给完整答案。结束时输出可粘贴回状态文件的“本次完成、证据、错误/风险、交接、下一步”五项更新。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴 Learning State]</span></span></code></pre></div><p>AI 生成的状态摘要不是事实来源。每次恢复时都以你保存的文件、作品、来源和版本号为准；完成一次周复盘后，按文件职责更新<a href="https://byoungd.github.io/up/templates/weekly-review" target="_blank" rel="noreferrer">每周复盘</a>、<a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链</a>和<a href="https://byoungd.github.io/up/templates/90-day-cycle" target="_blank" rel="noreferrer">九十日行动总表</a>，不要复制同一段记录。</p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/learning-state" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-06。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>`,33)])])}const p=e(r,[["render",n]]);export{c as __pageData,p as default};
